import {escapeHTML as esc,fa} from './model.js';

const KEY='hplgame-prototype-v1',TTL=30*86400000;
const empty=()=>({accounts:[],sessionId:null,guestGames:[],activeId:null});
let state=load(),warning='',pendingIdea='',queuedModal='',closeDialog;
const boards=new Map();
function cleanGame(g){return g&&typeof g.id==='string'&&typeof g.idea==='string'?{id:g.id,idea:g.idea.slice(0,600),step:Math.max(0,Math.min(3,Math.floor(Number(g.step))||0)),won:g.won===true,messages:Array.isArray(g.messages)?g.messages.filter(m=>m&&['user','coach'].includes(m.role)&&typeof m.text==='string').slice(-40).map(m=>({role:m.role,text:m.text.slice(0,3000)})):[]}:null;}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(!s||!Number.isFinite(s.updatedAt)||s.updatedAt>Date.now()+60000||Date.now()-s.updatedAt>TTL){localStorage.removeItem(KEY);return empty();}
 if(!Array.isArray(s.accounts))return {...empty(),guestGames:[cleanGame(s.game)].filter(Boolean),activeId:s.game?.id||null};
 const accounts=s.accounts.filter(a=>a&&typeof a.id==='string'&&typeof a.email==='string'&&typeof a.name==='string'&&/^[a-f0-9]{32}$/.test(a.salt)&&/^[a-f0-9]{64}$/.test(a.verifier)).slice(0,20).map(a=>({...a,name:a.name.slice(0,40),email:a.email.slice(0,254),premium:a.premium===true,games:(Array.isArray(a.games)?a.games:[]).map(cleanGame).filter(Boolean).slice(0,20)}));
 return {accounts,sessionId:accounts.some(a=>a.id===s.sessionId)?s.sessionId:null,guestGames:(Array.isArray(s.guestGames)?s.guestGames:[]).map(cleanGame).filter(Boolean).slice(0,1),activeId:typeof s.activeId==='string'?s.activeId:null};
 }catch{return empty();}}
function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,updatedAt:Date.now()}));warning='';}catch{warning='ذخیرهٔ مرورگر در دسترس نیست؛ این جلسه در حافظه ادامه دارد. برای نگهداری، خروجی بگیر.';}}
function account(){return state.accounts.find(a=>a.id===state.sessionId)||null;}
export function getDemoUser(){const a=account();return a?{name:a.name,premium:a.premium}:null;}
function games(){return account()?.games||state.guestGames;}
function game(){return games().find(g=>g.id===state.activeId)||games()[0]||null;}
function kind(g=game()){return /دوز|tic.?tac.?toe/i.test(g?.idea||'')?'tic':/مار|snake/i.test(g?.idea||'')?'snake':/فلپی|flappy|پرنده/i.test(g?.idea||'')?'flappy':'stars';}
const names={tic:'دوز',snake:'مار',flappy:'فلپی برد',stars:'جمع‌آوری ستاره'};
function lesson(g=game()){const type=kind(g),n=Math.min(g.step,2);return ({tic:['یک جدول ۳ در ۳ بساز. هر خانه خالی است؛ با کلیک، نوبت X و O عوض می‌شود.','خانهٔ اشغال‌شده را دوباره انتخاب نکن. نوبت‌ها باید یکی‌درمیان باشند.','اگر سه علامت همسان در یک سطر، ستون یا قطر قرار بگیرند، بازی تمام است.'],snake:['مار را روی یک شبکه می‌سازیم. با هر کلید جهت، سر مار یک خانه جلو می‌رود.','با خوردن غذا، یک خانه به طول مار اضافه کن. برخورد با دیوار یا بدن یعنی پایان بازی.','سه غذا جمع کن تا نمونهٔ کوتاه را ببری. روی بوم، کلیدهای جهت یا دکمه‌ها را امتحان کن.'],flappy:['پرنده را یک خانه بالا ببر؛ کلید بالا، Space یا کلیک روی بوم مثل بال‌زدن عمل می‌کند.','با حرکت به راست از شکاف لوله‌ها عبور کن. خانه‌های زرشکی مانع‌اند و برخورد، بازی را تمام می‌کند.','به لبهٔ راست بوم برس تا برنده شوی. مسیر بین مانع‌ها را با بالا و پایین تنظیم کن.'],stars:['یک بازیکن و سه ستاره در شبکه بگذار. هدف نسخهٔ اول، جمع کردن همین سه ستاره است.','کلیدهای جهت، بازیکن را یک خانه حرکت می‌دهند. اجازه نده از مرز بوم بیرون برود.','هر ستاره یک امتیاز دارد. پس از گرفتن هر سه ستاره، پیام برد را نشان بده.']})[type][n];}
function code(g=game()){return ({tic:['const cells = Array(9).fill(null);\nlet turn = "X";','if (!cells[index]) {\n  cells[index] = turn;\n  turn = turn === "X" ? "O" : "X";\n}','const lines = [[0,1,2],[3,4,5],[6,7,8],\n  [0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];\nconst won = lines.some(([a,b,c]) =>\n  cells[a] && cells[a] === cells[b] && cells[b] === cells[c]);'],snake:['let snake = [{x: 1, y: 1}];\nlet food = {x: 3, y: 1};','const head = {x: snake[0].x + dx, y: snake[0].y + dy};\nsnake.unshift(head);\nif (head.x !== food.x || head.y !== food.y) snake.pop();','if (outside || hitsBody) endGame();\nif (foodsCollected === 3) win();'],flappy:['let bird = {x: 0, y: 2};\nconst flap = () => bird.y = Math.max(0, bird.y - 1);','bird.x += 1;\nif (obstacles.some(p => p.x === bird.x && p.y === bird.y)) endGame();','if (bird.x === columns - 1) win();'],stars:['let player = {x: 0, y: 0};\nconst stars = [[5,0], [5,3], [0,3]];','player.x = Math.max(0, Math.min(5, player.x + dx));\nplayer.y = Math.max(0, Math.min(3, player.y + dy));','if (remainingStars.length === 0) win();']})[kind(g)][Math.min(g.step,2)];}
function add(role,text){game().messages.push({role,text:text.slice(0,3000)});game().messages=game().messages.slice(-40);}
export function submitPrototypeIdea(text,{navigate,render,toast}){text=String(text||'').trim();if(text.length<2||text.length>600){toast('ایده را بین ۲ تا ۶۰۰ نویسه بنویس.');return;}pendingIdea=text;
 const existing=games().find(g=>g.idea===text);if(existing){state.activeId=existing.id;pendingIdea='';save();navigate('studio/coach');return;}
 if(games().length>=1&&!account()?.premium){queuedModal='paywall';navigate('studio/coach');return;}
 if(games().length>=20){toast('ظرفیت ۲۰ بازی آزمایشی پر شده است. ابتدا داده‌ها را خروجی بگیر و پاک کن.');return;}
 const g={id:crypto.randomUUID(),idea:text,step:0,won:false,messages:[{role:'user',text}]};games().push(g);state.activeId=g.id;add('coach',`سلام! ایدهٔ «${text.slice(0,160)}» را شروع کنیم. ${lesson(g)}`);pendingIdea='';save();navigate('studio/coach');}
function boardMarkup(){return `<section class="panel proto-sandbox"><div class="section-head"><div><span class="badge">اجرای زندهٔ تمرین</span><h2>بوم ${names[kind()]}</h2></div><button class="btn secondary" data-proto="restart">شروع دوباره</button></div><canvas id="proto-canvas" width="480" height="320" tabindex="0" role="img" aria-label="بوم ${names[kind()]}؛ با جهت‌ها یا کلیک بازی کن"></canvas><p id="proto-game-status" role="status" aria-live="polite"></p><div class="proto-controls"><button class="btn primary" data-proto="run">اجرای بازی</button>${kind()==='tic'?'':['up','right','down','left'].map((d,i)=>`<button class="btn secondary" data-move="${d}" aria-label="حرکت ${['بالا','راست','پایین','چپ'][i]}">${['↑','→','↓','←'][i]}</button>`).join('')}</div><p class="proto-instructions">${kind()==='tic'?'بعد از اجرا، روی خانه‌های بوم کلیک کن. دو بازیکن به نوبت X و O می‌گذارند.':kind()==='flappy'?'نمونهٔ آموزشی گام‌به‌گام: بالا، Space یا کلیک برای بال‌زدن؛ راست برای پیشروی و پایین برای پایین‌آمدن. به لبهٔ راست برس.':'بعد از اجرا، بوم را لمس یا انتخاب کن و با جهت‌ها یا دکمه‌های پایین حرکت کن.'}</p></section>`;}
function coach(){const g=game();return `<div class="proto-workspace"><section class="panel coach-chat"><div class="chat-heading"><div class="hopi-bot" aria-hidden="true"><div class="bot-antenna"></div><div class="bot-face"><i></i><i></i><b></b></div><div class="bot-foot"></div></div><div><h2>هوپی، مربی تو</h2><small>راهنمای شبیه‌سازی‌شدهٔ متناسب با ایده</small></div></div><progress max="3" value="${g.step}" aria-label="پیشرفت آموزش"></progress><p>گام ${fa(Math.min(3,g.step+1))} از ۳ · ${['شروع ساخت','کنترل و قانون','تست و برد'][Math.min(2,g.step)]}${g.step===3?' · آموزش کامل شد ✓':''}</p><div class="chat-messages" role="log" aria-label="گفت‌وگو با هوپی" aria-live="polite">${g.messages.map(m=>`<div class="chat-message ${m.role}"><b>${m.role==='coach'?'هوپی':'تو'}</b><span>${esc(m.text)}</span></div>`).join('')}</div><div class="proto-quick"><button class="btn secondary" data-proto="next">گام بعدی</button><button class="btn secondary" data-proto="code">کد رو نشونم بده</button><button class="btn secondary" data-proto="question">سؤال دارم</button></div><form id="proto-chat"><label for="proto-message">پیام به هوپی</label><div class="proto-chat-row"><input id="proto-message" maxlength="500" required placeholder="مثلاً چطور ${kind()==='tic'?'نوبت‌ها را عوض کنم':'بازیکن را حرکت بدهم'}؟"><button class="btn primary">ارسال</button></div><p id="proto-chat-error" role="status"></p></form></section>${boardMarkup()}</div>`;}
function gameList(){return `<section class="panel"><div class="section-head"><h2>بازی‌های من</h2><button class="btn primary" data-proto="new">ساخت بازی جدید / بازی دوم</button></div><div class="proto-game-list">${games().map((g,i)=>`<article class="proto-game-card"><span class="badge">بازی ${fa(i+1)} · ${g.won?'برد ثبت شد':'در حال ساخت'}</span><h3>${esc(g.idea)}</h3><button class="btn secondary" data-open-game="${esc(g.id)}">ادامهٔ ساخت و بازی</button></article>`).join('')}</div><button class="btn secondary" data-proto="export">دانلود دادهٔ این نمونه</button><button class="btn ghost" data-proto="delete">پاک کردن دادهٔ پروتوتایپ</button></section>`;}
export function prototypePage(route){const view=route.split('/')[1]||'coach',g=game(),u=account();return `<section class="proto-heading"><div><span class="badge">کارگاه تعاملی · ${u?.premium?'پرمیوم آزمایشی':'اولین بازی رایگان'}</span><h1>${esc(u?.name||'بازی‌ساز')}، با هوپی بازی بساز.</h1><p>${g?esc(g.idea):'از یک ایدهٔ کوچک شروع کن؛ نتیجه را همین‌جا بازی کن.'}</p></div><div class="proto-quick">${u?'<button class="btn secondary" data-proto="logout">خروج آزمایشی</button>':'<button class="btn secondary" data-proto-auth="login">ورود / ثبت‌نام آزمایشی</button>'}<button class="btn primary" data-proto="new">ساخت بازی جدید / بازی دوم</button></div></section><nav class="proto-tabs" aria-label="بخش‌های کارگاه">${[['coach','مربی و بوم'],['preview','پیش‌نمایش بازی'],['games','بازی‌های من']].map(([id,t])=>`<a class="btn ${view===id?'primary':'secondary'}" href="#/studio/${id}" ${view===id?'aria-current="page"':''}>${t}</a>`).join('')}</nav>${g?(view==='games'?gameList():view==='preview'?boardMarkup():coach()):'<section class="panel proto-empty"><h2>چه بازی‌ای می‌خواهی بسازی؟</h2><form id="proto-first-idea"><label for="proto-idea">ایدهٔ اولین بازی</label><input id="proto-idea" maxlength="600" required placeholder="دوز، مار یا ایدهٔ خودت…"><p id="proto-idea-error" role="status"></p><button class="btn primary">شروع با هوپی</button></form></section>'}<p class="proto-storage" role="status">${esc(warning)}</p><div id="proto-modal-root"></div>`;}
function dialog(kind,ctx){closeDialog?.();let root=document.querySelector('#proto-modal-root');if(!root){root=document.createElement('div');root.id='proto-modal-root';document.body.append(root);}const previous=document.activeElement;
 root.innerHTML=`<div class="proto-backdrop"><section class="panel proto-dialog" role="dialog" aria-modal="true" aria-labelledby="proto-modal-title"><button class="btn ghost" data-close aria-label="بستن پنجره">×</button><div id="proto-dialog-content"></div></section></div>`;
 const dialogNode=root.querySelector('[role=dialog]'),content=root.querySelector('#proto-dialog-content'),inerted=[];let branch=root;
 while(branch.parentElement&&branch!==document.body){for(const sibling of branch.parentElement.children)if(sibling!==branch&&!sibling.inert){sibling.inert=true;inerted.push(sibling);}branch=branch.parentElement;}
 const close=()=>{root.innerHTML='';inerted.forEach(e=>e.inert=false);closeDialog=null;if(previous?.isConnected)previous.focus();};closeDialog=close;root.querySelector('[data-close]').onclick=close;
 root.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const nodes=[...dialogNode.querySelectorAll('button,input,a,select,textarea')].filter(x=>!x.disabled&&x.tabIndex!==-1),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
 function focus(){(content.querySelector('input')||content.querySelector('button')||root.querySelector('button')).focus();}
 if(kind==='login'||kind==='signup'){
  function auth(mode){content.innerHTML=`<span class="badge">حساب آزمایشی روی همین مرورگر</span><h2 id="proto-modal-title">${mode==='signup'?'به جمع بازی‌سازها بیا':'خوش برگشتی، بازی‌ساز!'}</h2><div class="proto-auth-tabs" role="tablist" aria-label="ورود و ثبت‌نام"><button class="btn ${mode==='login'?'primary':'secondary'}" role="tab" aria-selected="${mode==='login'}" data-auth-tab="login">ورود</button><button class="btn ${mode==='signup'?'primary':'secondary'}" role="tab" aria-selected="${mode==='signup'}" data-auth-tab="signup">ثبت‌نام</button></div><p>برای تست، از رمز مخصوص این نمونه استفاده کن. این حساب فقط روی این مرورگر است و ایمیل تأیید نمی‌شود.</p><form id="proto-auth" novalidate>${mode==='signup'?'<label for="proto-name">نام بازی‌ساز</label><input id="proto-name" name="name" autocomplete="nickname" maxlength="40" aria-describedby="proto-auth-error">':''}<label for="proto-email">ایمیل</label><input id="proto-email" name="email" type="email" dir="ltr" autocomplete="email" maxlength="254" aria-describedby="proto-auth-error"><label for="proto-password">رمز آزمایشی (حداقل ۸ نویسه)</label><input id="proto-password" name="password" type="password" dir="ltr" autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="8" maxlength="128" aria-describedby="proto-auth-error">${mode==='signup'?'<label for="proto-confirm">تکرار رمز</label><input id="proto-confirm" name="confirm" type="password" dir="ltr" autocomplete="new-password" maxlength="128" aria-describedby="proto-auth-error">':''}<p id="proto-auth-error" role="alert"></p><button class="btn primary" type="submit">${mode==='signup'?'ثبت‌نام و ورود':'ورود به کارگاه'}</button></form>`;
   content.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{if(!content.querySelector('form').dataset.busy)auth(b.dataset.authTab);});
   content.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.busy)return;const f=new FormData(form),email=String(f.get('email')||'').trim().toLowerCase(),password=String(f.get('password')||''),name=String(f.get('name')||'').trim(),error=content.querySelector('#proto-auth-error');let message='';
    if(mode==='signup'&&(name.length<2||name.length>40))message='نام را بین ۲ تا ۴۰ نویسه بنویس.';else if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)||email.length>254)message='یک ایمیل معتبر وارد کن.';else if(password.length<8||password.length>128)message='رمز باید ۸ تا ۱۲۸ نویسه باشد.';else if(mode==='signup'&&f.get('confirm')!==password)message='تکرار رمز با رمز یکسان نیست.';
    if(message){error.textContent=message;return;}
    const button=form.querySelector('[type=submit]');form.dataset.busy='true';button.disabled=true;error.textContent='در حال بررسی…';
    try{let a=state.accounts.find(a=>a.email===email);
     if(mode==='signup'){if(a)throw Error('این ایمیل قبلاً ثبت شده؛ از تب ورود استفاده کن.');if(state.accounts.length>=20)throw Error('ظرفیت حساب‌های آزمایشی این مرورگر پر شده است.');const salt=hex(crypto.getRandomValues(new Uint8Array(16))),verifier=await passwordHash(password,salt);a={id:crypto.randomUUID(),name,email,salt,verifier,premium:false,games:state.guestGames};state.guestGames=[];state.accounts.push(a);}
     else if(!a||await passwordHash(password,a.salt)!==a.verifier)throw Error('ایمیل یا رمز درست نیست. برای حساب جدید، ثبت‌نام را انتخاب کن.');
     state.sessionId=a.id;state.activeId=a.games[0]?.id||null;save();close();ctx.toast('وارد شدی؛ خوش آمدی '+a.name);if(pendingIdea)submitPrototypeIdea(pendingIdea,ctx);else ctx.navigate('studio/coach');
    }catch(err){error.textContent=err.message==='crypto_unavailable'?'مرورگر امکان بررسی امن رمز را ندارد؛ با HTTPS یا localhost باز کن.':err.message||'ورود انجام نشد؛ دوباره امتحان کن.';}finally{delete form.dataset.busy;button.disabled=false;}
   };focus();}
  auth(kind);
 }else if(kind==='paywall'){
  content.innerHTML='<span class="badge">HPLGAME PRO · اشتراک ماهانه</span><h2 id="proto-modal-title">برای بازی بعدی، یک قدم جلوتر برو ✦</h2><p>اولین بازی تو رایگان می‌ماند. برای ساخت پروژهٔ دوم و بیشتر، پلن پرو لازم است.</p><div class="proto-pro-features"><span>✦ چند پروژهٔ هم‌زمان</span><span>✦ ادامهٔ مسیرهای بیشتر</span><span>✦ مدیریت بازی‌ها</span></div><p>فعلاً پرداخت واقعی نداریم؛ حساب پرمیوم آزمایشی، قابلیت چندبازی را در همین مرورگر باز می‌کند.</p><button class="btn primary" id="proto-upgrade">ارتقا به پرمیوم آزمایشی</button><p id="proto-plan-status" role="status"></p><button class="btn secondary" id="proto-free">ادامهٔ بازی رایگان</button>';
  content.querySelector('#proto-free').onclick=()=>{pendingIdea='';close();};content.querySelector('#proto-upgrade').onclick=()=>{const a=account();if(!a){close();dialog('signup',ctx);ctx.toast('ابتدا یک حساب آزمایشی بساز؛ سپس پرمیوم را فعال کن.');return;}a.premium=true;save();close();ctx.render();ctx.toast('پرمیوم آزمایشی فعال شد؛ پرداختی انجام نشد.');if(pendingIdea)submitPrototypeIdea(pendingIdea,ctx);else dialog('new',ctx);};focus();
 }else if(kind==='new'){
  content.innerHTML='<h2 id="proto-modal-title">ایدهٔ بازی جدیدت چیست؟</h2><form id="proto-new-game"><label for="proto-new-idea">ایدهٔ بازی</label><textarea id="proto-new-idea" maxlength="600" required></textarea><p id="proto-new-error" role="status"></p><button class="btn primary">ساخت بازی و شروع آموزش</button></form>';content.querySelector('form').onsubmit=e=>{e.preventDefault();const text=content.querySelector('textarea').value.trim();if(text.length<2){content.querySelector('#proto-new-error').textContent='حداقل دو نویسه بنویس.';return;}close();submitPrototypeIdea(text,ctx);};focus();
 }else if(kind==='delete'){
  content.innerHTML='<h2 id="proto-modal-title">پاک کردن دادهٔ نمونه؟</h2><p>تمام حساب‌ها و بازی‌های آزمایشی همین مرورگر حذف می‌شوند. ایده و پژوهش هفته‌های قبل باقی می‌مانند.</p><button class="btn primary" id="proto-confirm-delete">بله، دادهٔ نمونه پاک شود</button><button class="btn secondary" id="proto-cancel-delete">انصراف</button>';content.querySelector('#proto-cancel-delete').onclick=close;content.querySelector('#proto-confirm-delete').onclick=()=>{state=empty();pendingIdea='';boards.clear();try{localStorage.removeItem(KEY);}catch{}close();ctx.navigate('studio/coach');ctx.render();};focus();
 }
}
function hex(bytes){return [...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function passwordHash(password,salt){if(!crypto.subtle)throw Error('crypto_unavailable');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return hex(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256)));}
function reply(text){if(/کد|code/i.test(text))return 'نمونهٔ کد همین گام (آموزشی و بدون اجرای متن ورودی):\n'+code();if(/برد|باخت|برنده|امتیاز/.test(text))return lesson({...game(),step:2});if(/حرکت|کنترل|کلید|نوبت|غذا|لوله/.test(text))return lesson({...game(),step:1});if(/سلام/.test(text))return `سلام! داریم ${names[kind()]} می‌سازیم. ${lesson()}`;if(/سؤال دارم/.test(text))return `بپرس! دربارهٔ ${kind()==='tic'?'خانه‌ها، نوبت X و O یا شرط برد':kind()==='snake'?'حرکت مار، غذا یا برخورد':kind()==='flappy'?'بال‌زدن، لوله‌ها یا رسیدن به پایان':'حرکت، ستاره‌ها یا شرط برد'} سؤال داری؟`;return `برای «${game().idea.slice(0,100)}» در این گام: ${lesson()} اگر کد می‌خواهی «کد رو نشونم بده» را بزن و روی بوم نتیجه را آزمایش کن.`;}
export function bindPrototype(ctx){closeDialog?.();const {render,navigate,toast}=ctx;
 document.querySelectorAll('[data-proto-auth]').forEach(b=>b.onclick=e=>{e.preventDefault();dialog(b.dataset.protoAuth||'login',ctx);});
 document.querySelector('#proto-first-idea')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#proto-idea').value.trim();if(text.length<2){document.querySelector('#proto-idea-error').textContent='حداقل دو نویسه بنویس.';return;}submitPrototypeIdea(text,ctx);});
 function chat(text){add('user',text);add('coach',reply(text));save();render();document.querySelector('#proto-message')?.focus();}
 document.querySelector('#proto-chat')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#proto-message').value.trim();if(!text){document.querySelector('#proto-chat-error').textContent='سؤالت را بنویس یا یک پاسخ سریع انتخاب کن.';return;}chat(text.slice(0,500));});
 document.querySelectorAll('[data-open-game]').forEach(b=>b.onclick=()=>{state.activeId=b.dataset.openGame;save();navigate('studio/coach');});
 document.querySelectorAll('[data-proto]').forEach(b=>b.addEventListener('click',()=>{switch(b.dataset.proto){case'new':dialog(games().length&&!account()?.premium?'paywall':'new',ctx);break;case'next':add('user','گام بعدی');if(game().step<3)game().step++;add('coach',game().step===3?'سه گام را تمام کردی! حالا روی بوم بازی کن؛ شروع اجرا به‌تنهایی برد نیست. می‌توانی کد و راهنمای هر گام را هم بخواهی.':lesson());save();render();break;case'code':chat('کد رو نشونم بده');break;case'question':chat('سؤال دارم');break;case'logout':state.sessionId=null;state.activeId=null;save();render();toast('از حساب آزمایشی خارج شدی.');break;case'export':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({scope:'local-prototype',games:games()},null,2)],{type:'application/json'}));a.href=url;a.download='hplgame-prototype.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'delete':dialog('delete',ctx);break;}}));
 const canvas=document.querySelector('#proto-canvas');if(canvas)bindBoard(canvas);const log=document.querySelector('.proto-workspace .chat-messages');if(log)log.scrollTop=log.scrollHeight;
 if(queuedModal){const m=queuedModal;queuedModal='';dialog(m,ctx);}else if(/^#\/studio\/(login|signup)$/.test(location.hash)){const mode=location.hash.endsWith('signup')?'signup':'login';dialog(mode,ctx);}
}
function bindBoard(canvas){const g=game(),type=kind(g),ctx=canvas.getContext('2d'),status=document.querySelector('#proto-game-status');let b=boards.get(g.id);
 function reset(){b={running:false,ended:false,x:type==='snake'?1:0,y:type==='snake'?1:2,snake:[{x:1,y:1}],foodIndex:0,stars:['5,0','5,3','0,3'],cells:Array(9).fill(null),turn:'X',message:'برای شروع، اجرای بازی را بزن.'};if(type==='stars')b.y=0;boards.set(g.id,b);draw();}
 const obstacles=['2,0','2,3','4,0','4,1'],foods=[{x:3,y:1},{x:3,y:3},{x:0,y:3}];
 function finish(won,message){b.running=false;b.ended=true;b.message=message;if(won){g.won=true;save();}}
 function draw(){status.textContent=b.message;if(!ctx)return;ctx.fillStyle='#24151f';ctx.fillRect(0,0,480,320);const cols=type==='tic'?3:6,rows=type==='tic'?3:4,cw=480/cols,ch=320/rows;ctx.strokeStyle='#754052';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)ctx.strokeRect(x*cw+1,y*ch+1,cw-2,ch-2);ctx.font='36px sans-serif';ctx.textAlign='center';
  if(type==='tic'){b.cells.forEach((v,i)=>{if(v){ctx.fillStyle=v==='X'?'#ffd58a':'#be3144';ctx.fillText(v,(i%3)*cw+cw/2,Math.floor(i/3)*ch+ch/2+12);}});return;}
  if(type==='stars'){ctx.fillStyle='#ffd58a';for(const pos of b.stars){const [x,y]=pos.split(',').map(Number);ctx.fillText('★',x*80+40,y*80+53);}}
  if(type==='flappy'){ctx.fillStyle='#872341';for(const p of obstacles){const [x,y]=p.split(',').map(Number);ctx.fillRect(x*80+7,y*80+7,66,66);}}
  if(type==='snake'){const food=foods[Math.min(2,b.foodIndex)];ctx.fillStyle='#ffd58a';ctx.fillText('●',food.x*80+40,food.y*80+53);ctx.fillStyle='#be3144';b.snake.forEach(p=>ctx.fillRect(p.x*80+12,p.y*80+12,56,56));}else{ctx.fillStyle='#be3144';ctx.beginPath();ctx.arc(b.x*80+40,b.y*80+40,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.fillText(type==='flappy'?'◒':'●',b.x*80+40,b.y*80+52);}}
 function move(dir){if(!b.running){b.message=b.ended?'بازی تمام شده؛ برای تمرین دوباره، اجرای بازی را بزن.':'اول اجرای بازی را بزن.';draw();return;}if(type==='tic')return;const dx=dir==='right'?1:dir==='left'?-1:0,dy=dir==='down'?1:dir==='up'?-1:0;let x=b.x+dx,y=b.y+dy;
  if(type==='snake'){const food=foods[b.foodIndex],eating=x===food.x&&y===food.y,body=eating?b.snake:b.snake.slice(0,-1);if(x<0||x>5||y<0||y>3||body.some(p=>p.x===x&&p.y===y)){finish(false,'با دیوار یا بدن مار برخورد کردی؛ دوباره امتحان کن.');draw();return;}b.snake.unshift({x,y});if(eating)b.foodIndex++;else b.snake.pop();}
  else{x=Math.max(0,Math.min(5,x));y=Math.max(0,Math.min(3,y));}b.x=x;b.y=y;
  if(type==='stars')b.stars=b.stars.filter(p=>p!==`${x},${y}`);
  b.message=`خانهٔ ${fa(x+1)}، ${fa(y+1)} · ${type==='snake'?fa(b.foodIndex)+' از ۳ غذا':type==='stars'?fa(3-b.stars.length)+' از ۳ ستاره':'از شکاف لوله‌ها عبور کن'}`;
  if(type==='flappy'&&obstacles.includes(`${x},${y}`))finish(false,'به لوله برخورد کردی؛ دوباره امتحان کن.');else if(type==='snake'&&b.foodIndex===3||type==='stars'&&!b.stars.length||type==='flappy'&&x===5)finish(true,'آفرین! برنده شدی؛ می‌توانی دوباره بازی کنی.');draw();}
 document.querySelector('[data-proto=run]').onclick=()=>{if(b.ended)reset();b.running=true;b.message=type==='tic'?`نوبت ${b.turn}؛ یک خانه را انتخاب کن.`:'بازی شروع شد؛ با جهت‌ها بازی کن.';draw();canvas.focus();};document.querySelector('[data-proto=restart]').onclick=reset;document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>move(el.dataset.move));
 canvas.onkeydown=e=>{const d={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[e.key];if(d||type==='flappy'&&e.code==='Space'){e.preventDefault();move(d||'up');}};
 canvas.onclick=e=>{if(type==='flappy'){move('up');return;}if(type!=='tic')return;if(!b.running){b.message='اول اجرای بازی را بزن.';draw();return;}const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const x=Math.floor((e.clientX-rect.left)/rect.width*3),y=Math.floor((e.clientY-rect.top)/rect.height*3),index=y*3+x;if(x<0||x>2||y<0||y>2)return;if(b.cells[index]){b.message='این خانه پر است؛ یک خانهٔ خالی انتخاب کن.';draw();return;}b.cells[index]=b.turn;const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];if(lines.some(([a,c,d])=>b.cells[a]&&b.cells[a]===b.cells[c]&&b.cells[a]===b.cells[d]))finish(true,`${b.turn} برنده شد! برای بازی دوباره، اجرا را بزن.`);else if(b.cells.every(Boolean))finish(false,'مساوی شد! دوباره بازی کن.');else{b.turn=b.turn==='X'?'O':'X';b.message=`نوبت ${b.turn} است.`;}draw();};if(!b)reset();else draw();
}
